CREATE FUNCTION public.czy_ksiazka_dostepna(p_isbn character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ilosc INT;
BEGIN
    SELECT COUNT(*) INTO v_ilosc 
    FROM ksiazki 
    WHERE nr_isbn = p_isbn AND status = 'dostÄ™pny';
    
    IF v_ilosc > 0 THEN
        RETURN TRUE;
    ELSE
        RETURN FALSE;
    END IF;
END;
$$;


